{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C13","C24","C31","C38","C12","C65","C66","C67","C68","C69","C73","C74","C77","C78","C80","C81","C82","C83","C84","C85","C87"],
  "contradictory_card_ids": ["C70","C75"],
  "prediction_basis_card_ids": ["C01","C13","C24","C31","C38","C12","C65","C66","C67","C68","C69","C73","C74","C77","C78","C80","C81","C82","C83","C84","C85","C87"],
  "claims": [
    {
      "claim": "EM574, a closely related macrolide, has very low human oral bioavailability (~2%) inferred from mean oral CL/F ~4500 L/h, with low FgFh in rabbits (2.4–3.3%) and low F in rats/dogs; this is the most transferable direct F evidence for the query macrolide.",
      "card_ids": ["C01","C13","C24","C31","C38"]
    },
    {
      "claim": "YH4808 provides a direct human absolute F of 10.1% (range 2.3–19.3%), below the 20% threshold, though it is structurally distant from the query.",
      "card_ids": ["C12"]
    },
    {
      "claim": "L6 hepatic-clearance records show erythromycin and clarithromycin have measurable intrinsic clearance in rat assays (erythromycin 11.4±2.2 and 16.2±6.7 µL/min/mg; clarithromycin 9.1±0.3 and 16.2±3.4 µL/min/mg), erythromycin CLint in humans estimated 8.1–105 L/h, and tacrolimus/pimecrolimus are extensively metabolized by CYP3A4; this mechanistically supports hepatic first-pass loss for the macrolide class, but is not a direct F measurement.",
      "card_ids": ["C77","C78","C82","C83","C85","C87","C80","C84","C81"]
    },
    {
      "claim": "L5 gut-wall records show macrolide/immunosuppressant drugs are P-gp substrates and/or undergo intestinal CYP3A4 metabolism, with increased AUC in Mdr1-knockout mice or with P-gp inhibitors; this mechanistically supports presystemic loss.",
      "card_ids": ["C65","C66","C67","C68","C69","C73","C74"]
    },
    {
      "claim": "High Caco-2 permeability for clarithromycin/roxithromycin and everolimus (C70, C75) shows that high permeability alone does not establish F >= 20% and does not outweigh the direct low-F macrolide evidence.",
      "card_ids": ["C70","C75"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C77","C78","C80","C81","C82","C83","C84","C85","C87"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute F measurement exists for the exact query macrolide.",
    "EM574 is closely related but not identical; differences in sugar substitution, absence of HBD, and aglycone may alter absorption or metabolism.",
    "No query-specific hepatic clearance, P-gp/CYP3A4, or intestinal metabolism data were supplied; L6 records are for other macrolides/immunosuppressants.",
    "No quantitative solubility, permeability, or metabolic stability data for the query were supplied.",
    "Formulation, food effects, and first-pass enzyme contributions for the query are unknown.",
    "L6 intrinsic-clearance values are in vitro rat/human estimates, not direct oral-bioavailability results."
  ],
  "decision_summary": "Prediction remains low and is strengthened by L6 hepatic-clearance/CYP3A4 evidence for macrolides, consistent with EM574's very low human F and YH4808's subthreshold F. High-permeability records for other macrolides are indirect and do not establish F >= 20%. Confidence remains moderate."
}

